export class StadiumAudioController {
 constructor(){this.enabled=false;this.context=null;this.lastStep=-1;this.lastVoice=-100;this.time=0;}
 async setEnabled(value){this.enabled=value;if(!value){this.context?.suspend();globalThis.speechSynthesis?.cancel();return;}const Context=globalThis.AudioContext||globalThis.webkitAudioContext;if(!Context)return;try{if(!this.context){const c=this.context=new Context();this.master=c.createGain();this.master.gain.value=.65;this.master.connect(c.destination);const noise=c.createBuffer(1,c.sampleRate*2,c.sampleRate),channel=noise.getChannelData(0);let smooth=0;for(let i=0;i<channel.length;i++){smooth=smooth*.92+(Math.random()*2-1)*.08;channel[i]=smooth;}const source=c.createBufferSource();source.buffer=noise;source.loop=true;const filter=c.createBiquadFilter();filter.type='bandpass';filter.frequency.value=850;filter.Q.value=.35;this.crowd=c.createGain();this.crowd.gain.value=.02;source.connect(filter).connect(this.crowd).connect(this.master);source.start();}await this.context.resume();}catch{this.enabled=false;}}
 tone(frequency,duration,volume=.1,type='triangle'){if(!this.enabled||!this.context)return;const c=this.context,o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(frequency,c.currentTime);o.frequency.exponentialRampToValueAtTime(Math.max(25,frequency*.4),c.currentTime+duration);g.gain.setValueAtTime(volume,c.currentTime);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+duration);o.connect(g).connect(this.master);o.start();o.stop(c.currentTime+duration);}
 event(type){if(type==='contact')this.tone(610,.10,.19);if(type==='bounce')this.tone(110,.045,.035);if(type==='wicket'){this.tone(165,.16,.2,'square');this.say('Bowled him!');}if(type==='four'||type==='six'){this.tone(240,.45,.06);this.say(type==='six'?'That is a huge six!':'Beautiful shot.');}if(type==='miss')this.say('Watch the hand.');if(type==='tap')this.tone(150,.05,.025);}
 say(text){if(!this.enabled||this.time-this.lastVoice<6||!globalThis.speechSynthesis||!globalThis.SpeechSynthesisUtterance)return;this.lastVoice=this.time;const u=new SpeechSynthesisUtterance(text);u.volume=.3;u.rate=1.08;u.pitch=.8;globalThis.speechSynthesis.speak(u);}
 clap(volume){if(!this.enabled||!this.context)return;const c=this.context;if(!this.clapBuffer){this.clapBuffer=c.createBuffer(1,Math.floor(c.sampleRate*.09),c.sampleRate);const data=this.clapBuffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*Math.exp(-i/(c.sampleRate*.013));}const source=c.createBufferSource(),gain=c.createGain();source.buffer=this.clapBuffer;gain.gain.value=volume;source.connect(gain).connect(this.master);source.start();}
 chant(){if(!this.enabled||!this.context)return;const c=this.context;for(const f of [112,146,190]){const o=c.createOscillator(),filter=c.createBiquadFilter(),gain=c.createGain();o.type='sawtooth';o.frequency.value=f;filter.type='bandpass';filter.frequency.value=700;filter.Q.value=2;gain.gain.value=.001;for(let i=0;i<3;i++){gain.gain.setValueAtTime(.001,c.currentTime+i*.45);gain.gain.linearRampToValueAtTime(.015,c.currentTime+i*.45+.08);gain.gain.exponentialRampToValueAtTime(.001,c.currentTime+i*.45+.39);}o.connect(filter).connect(gain).connect(this.master);o.start();o.stop(c.currentTime+1.4);}}
 update(dt,state,intensity,runProgress=0,paused=false){this.time+=dt;if(!this.enabled||!this.context)return;this.crowd.gain.setTargetAtTime(paused?.004:.035+intensity*.48,this.context.currentTime,.15);if(state==='runup'&&!paused){const step=Math.floor(runProgress*15);if(step!==this.lastStep){this.lastStep=step;this.tone(75,.065,.018+runProgress*.05);}}else this.lastStep=-1;if(!paused&&intensity>.35&&Math.floor(this.time*9)!==this.lastClap){this.lastClap=Math.floor(this.time*9);this.clap(.03*intensity);}if(!paused&&intensity>.7&&this.time-(this.lastChant??-10)>5){this.lastChant=this.time;this.chant();}}
}
